+ATapDataModel * TrafficTree::dataModel()
+{
+    QSortFilterProxyModel * proxy = qobject_cast<QSortFilterProxyModel *>(model());
+    if (proxy)
+        return qobject_cast<ATapDataModel *>(proxy->sourceModel());
+    return nullptr;
+}
