+void TrafficTree::clipboardAction()
+{
+    QAction * ca = qobject_cast<QAction *>(sender());
+    if (ca && ca->property("copy_as").isValid())
+        copyToClipboard((eTrafficTreeClipboard)ca->property("copy_as").toInt());
+}
